const HM = () => devUserName('HIRING_MANAGER');
const AM = () => devUserName('ACCOUNT_MANAGER');
const TL = () => devUserName('TEAM_LEAD');
const HR = () => devUserName('HR_HEAD');
const HRM = () => devUserName('HR_MANAGER');
function daysFromNow(days) {
    const d = new Date();
    d.setHours(12, 0, 0, 0);
    d.setDate(d.getDate() + days);
    return d.toISOString().slice(0, 10);
}
