const SOURCES = [
    'LinkedIn',
    'Naukri',
    'Employee Referral',
    'Direct Application',
    'Recruiter Added',
    'Candidate Portal',
    'Agency',
];
function cand(b) {
    const y = b.years;
    const base = Math.max(6, y * 3 + 2);
    const slug = b.name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
    const panSeed = [...b.email].reduce((a, c) => a + c.charCodeAt(0), 0);
    return {
        email: b.email,
        name: b.name,
        role: b.role,
        status: b.status,
        source: b.vendor ? 'Vendor: TalentBridge Staffing Solutions' : b.source ?? SOURCES[panSeed % SOURCES.length],
        jobCode: b.jobCode,
        phone: b.phone ?? `+91 9${String(800000000 + (panSeed % 199999999)).slice(0, 9)}`,
        location: b.location,
        totalExperience: `${y} Years`,
        currentCompany: b.company,
        currentCTC: b.currentCTC ?? `${base} LPA`,
        expectedCTC: b.expectedCTC ?? `${base + Math.max(3, Math.round(base * 0.22))} LPA`,
        noticePeriod: b.noticePeriod ?? (y >= 7 ? '90 Days' : y >= 4 ? '60 Days' : '30 Days'),
        pan: `XYZP${String.fromCharCode(65 + (panSeed % 26))}${String(1000 + (panSeed % 9000))}${String.fromCharCode(65 + ((panSeed >> 3) % 26))}`,
        linkedIn: `https://www.linkedin.com/in/${slug}`,
        primarySkills: b.skills,
        secondarySkills: b.secondary,
        resumeSnippet: `${b.name} — ${b.role} at ${b.company}, ${y} years. ${b.skills.slice(0, 4).join(', ')}. Based in ${b.location}.`,
        vendorSubmitted: b.vendor,
        interviewProgress: b.interviewProgress,
        offerStatus: b.offerStatus,
    };
}
